    query: "SELECT count() FROM analytics.events_sink",
    format: "JSONEachRow",
  });
  const elapsed = Date.now() - start;
  const passed = elapsed < 100;
  return {
    passed,
    message: passed ? "Sink query under 100ms." : `Sink query took ${elapsed}ms.`,
    details: { elapsedMs: elapsed },
  };
}

